function r8e_start($args,&$pipes){$cmd=escapeshellarg(PHP_BINARY).' '.escapeshellarg(__DIR__.'/review_worker.php');foreach($args as$v)$cmd.=' '.escapeshellarg((string)$v);$p=proc_open($cmd,[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);vcw_assert_true(is_resource($p),'review worker start');return$p;}
function r8e_start_followup($args,&$pipes){$cmd=escapeshellarg(PHP_BINARY).' '.escapeshellarg(__DIR__.'/review_followup_worker.php');foreach($args as$v)$cmd.=' '.escapeshellarg((string)$v);$p=proc_open($cmd,[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);vcw_assert_true(is_resource($p),'follow-up worker start');return$p;}
function r8e_file($f){$d=microtime(true)+15;while(!is_file($f)&&microtime(true)<$d)usleep(100000);vcw_assert_true(is_file($f),'worker announce');return json_decode(file_get_contents($f),true);}
function r8e_get($p,$pipes){foreach($pipes as$x)stream_set_blocking($x,false);$o='';$e='';$deadline=microtime(true)+20.0;do{$o.=stream_get_contents($pipes[1]);$e.=stream_get_contents($pipes[2]);$s=proc_get_status($p);if(!$s['running'])break;usleep(50000);}while(microtime(true)<$deadline);if(($s['running']??false)){proc_terminate($p);$killDeadline=microtime(true)+2.0;do{$s=proc_get_status($p);if(!$s['running'])break;usleep(50000);}while(microtime(true)<$killDeadline);}$o.=stream_get_contents($pipes[1]);$e.=stream_get_contents($pipes[2]);foreach($pipes as$x)fclose($x);$code=proc_close($p);vcw_assert_same(0,$code,'worker exit code='.$code.' stderr='.trim($e).' stdout='.trim($o));$decoded=json_decode(trim($o),true);vcw_assert_true(is_array($decoded),'worker JSON output');return$decoded;}
function r8e_pw(){ $i=json_decode(shell_exec('docker inspect visit_clinical_workflow-db-1'),true);foreach(($i[0]['Config']['Env']??[])as$e)if(strpos($e,'MARIADB_ROOT_PASSWORD=')===0)return substr($e,22);return''; }
function r8e_edges($pw){$q='SELECT r.trx_mysql_thread_id,b.trx_mysql_thread_id FROM information_schema.INNODB_LOCK_WAITS w JOIN information_schema.INNODB_TRX r ON r.trx_id=w.requesting_trx_id JOIN information_schema.INNODB_TRX b ON b.trx_id=w.blocking_trx_id';$o=(string)shell_exec('docker exec visit_clinical_workflow-db-1 mariadb -N -B -uroot -p'.escapeshellarg($pw).' doclinc_visit_test -e '.escapeshellarg($q));$r=[];foreach(preg_split('/\r?\n/',trim($o))as$l)if(preg_match('/^(\d+)\s+(\d+)$/',$l,$m))$r[]=[(int)$m[1],(int)$m[2]];return$r;}
function r8e_wait($pw,$edges){$d=microtime(true)+15;while(microtime(true)<$d){$a=r8e_edges($pw);if(!array_filter($edges,fn($e)=>!in_array($e,$a,true)))return;usleep(100000);}vcw_assert_true(false,'wait graph');}
function r8e_abort($p,&$pipes){if(is_resource($p)){@proc_terminate($p);$deadline=microtime(true)+2.0;do{$s=@proc_get_status($p);if(!$s||!$s['running'])break;usleep(50000);}while(microtime(true)<$deadline);foreach($pipes as$x)@fclose($x);@proc_close($p);}}
function r8e_race($db,$pw,$tmp,$fx,$a,$b,$tag){$ready=$tmp.'/'.$tag.'.g';$release=$tmp.'/'.$tag.'.r';$gp=[];$g=null;$ap=[];$wa=null;$bp=[];$wb=null;$released=false;$collected=false;try{$g=proc_open(escapeshellarg(PHP_BINARY).' '.escapeshellarg(__DIR__.'/row_lock_gate_worker.php').' '.escapeshellarg('request').' '.escapeshellarg($fx['request']).' '.escapeshellarg($ready).' '.escapeshellarg($release),[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$gp);$gi=r8e_file($ready);$af=$tmp.'/'.$tag.'.a';$wa=r8e_start(array_merge([$fx['request'],$fx['result']],$a,[$af]),$ap);$ai=r8e_file($af);r8e_wait($pw,[[$ai['connection_id'],$gi['connection_id']]]);$bf=$tmp.'/'.$tag.'.b';$wb=r8e_start(array_merge([$fx['request'],$fx['result']],$b,[$bf]),$bp);$bi=r8e_file($bf);r8e_wait($pw,[[$ai['connection_id'],$gi['connection_id']],[$bi['connection_id'],$ai['connection_id']]]);file_put_contents($release,'x');$released=true;$ar=r8e_get($wa,$ap);$wa=null;$br=r8e_get($wb,$bp);$wb=null;$gr=r8e_get($g,$gp);$g=null;$collected=true;return[$ai,$bi,$gi,$ar,$br];}finally{if(!$released)@file_put_contents($release,'abort');if(!$collected){r8e_abort($wa,$ap);r8e_abort($wb,$bp);r8e_abort($g,$gp);}}}
$max=$db->query('SELECT COALESCE(MAX(request_id),0) m FROM requests')->row();$base=(int)$max->m+15000;$tmp=sys_get_temp_dir().DIRECTORY_SEPARATOR.'r8e-'.$base.'-'.getmypid();vcw_assert_true(mkdir($tmp),'concurrency temp directory');$pw=r8e_pw();vcw_assert_true($pw!=='','root observer');
