$fxApproval=r8e_fixture($db,$base+220);$dualApproval=r8e_race($db,$pw,$tmp,$fxApproval,[$fxApproval['rd'],'approved','-','-','rd-approval-key-'.$base],[$fxApproval['p'],'approved','-','-','performer-approval-key-'.$base],'dual-approval');$approvalRow=$db->where('visit_result_id',$fxApproval['result'])->get('clinical_reviews')->row();$approvalAssignment=$db->where('visit_assignment_id',$fxApproval['a'])->get('request_visit_performer_assignments')->row();vcw_assert_same('approved',(string)$approvalRow->decision,'dual authority approval winner');vcw_assert_same('selesai',(string)$approvalAssignment->status,'dual authority approval completes assignment');vcw_assert_true(!(($approvalRow->responsible_assignment_id!==null)&&($approvalRow->reviewer_visit_assignment_id!==null)),'dual authority approval xor provenance');
$replayFx=r8e_fixture($db,$base+240);$replayService=new Clinical_review_service($db);$replayKey='historical-'.$replayFx['result'].'-'.$base;$seed=$replayService->review($replayFx['request'],$replayFx['result'],$replayFx['rd'],'correction_required','Reason','Notes',$replayKey);vcw_assert_same('success',$seed['status']??null,'historical replay seed');$replayed=$replayService->review($replayFx['request'],$replayFx['result'],$replayFx['rd'],'correction_required','Reason','Notes',$replayKey);vcw_assert_true(!empty($replayed['idempotent'])&&(int)$replayed['clinical_review_id']===(int)$seed['clinical_review_id'],'historical replay immutable');$followup=(new Visit_result_service($db))->createCorrectionDraft($replayFx['request'],$replayFx['p'],$replayFx['result'],'draft-'.$base);vcw_assert_same('success',$followup['status']??null,'legitimate later correction progression');vcw_assert_same(1,(int)$db->where('visit_result_id',$replayFx['result'])->count_all_results('clinical_reviews'),'historical replay review count');vcw_assert_same(1,(int)$db->where('request_id',$replayFx['request'])->where('event_type','visit_result.correction_required')->count_all_results('request_events'),'historical replay event count');$placement=new Nakes_placement_store($db);$approvalBlockers=$placement->blockers($fxApproval['p']);vcw_assert_true(!array_filter($approvalBlockers,fn($b)=>($b['kind']??'')==='visit_performer'),'approval placement blocker cleared');$correctionFx=r8e_fixture($db,$base+260);$correctionService=new Clinical_review_service($db);$correctionSeed=$correctionService->review($correctionFx['request'],$correctionFx['result'],$correctionFx['rd'],'correction_required','Reason','Notes','placement-'.$base);vcw_assert_same('success',$correctionSeed['status']??null,'correction placement seed');$correctionBlockers=$placement->blockers($correctionFx['p']);vcw_assert_true((bool)array_filter($correctionBlockers,fn($b)=>($b['kind']??'')==='visit_performer'),'correction placement blocker remains')